blocks.text:
terraform {
  required_version = ">= 1.6.6"
  backend "s3" {
    bucket         = "ns-tf-state"
    key            = "clh-recon/prod/msk/terraform.tfstate"
    region         = "us-east-1"
    dynamodb_table = "ns-tf-lock"
    encrypt        = true
    kms_key_id     = "alias/ns-tf-state"
  }
  required_providers {
    aws = { source = "hashicorp/aws", version = "5.41.0" }
  }
}

# from a runner, never from a random laptop against prod
export AWS_ROLE_ARN=arn:aws:iam::881736291104:role/ns-gha-tf-clh-recon
aws sts assume-role --role-arn $AWS_ROLE_ARN --role-session-name tf-msk-prod
terraform -chdir=infra/live/prod/clh-recon/msk init
terraform -chdir=infra/live/prod/clh-recon/msk plan -out=msk.plan
terraform -chdir=infra/live/prod/clh-recon/msk show -json msk.plan | jq '.resource_changes[] | {addr:.address, actions:.change.actions}'

variable "broker_count" {
  type = number
  validation {
    condition     = var.broker_count == 3 || var.broker_count == 6
    error_message = "Broker count is 3 or 6. Other values are an incident report."
  }
}

# in CI, fail the apply job if ET hour is 16, 17, 18, 19
# see .github/workflows/tf-clh-recon.yml step "window-guard"
python3 tools/window_guard.py --freeze-hours 16-19 --tz America/New_York --also-block-sat-sun
